// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PredictTheBlockHashChallenge c;

    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function _run(bytes32 guessHash, uint256 sendForLock) internal {
        sendForLock = bound(sendForLock, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendForLock);
        uint balBefore = address(c).balance;
        bool lockReverted;
        try c.lockInGuess{value: sendForLock}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }
        uint balAfter = address(c).balance;
        bool secondSettleReverted;
        try c.settle() {
            secondSettleReverted = false;
        } catch {
            secondSettleReverted = true;
        }
        assertTrue(settleReverted || (
                // balance decreased by at most 2 ether
                balAfter + 2 ether >= balBefore &&
                // second settle reverted, indicating stored guess cleared
                secondSettleReverted
            ));
    }

    function testFuzz_run(bytes32 guessHash, uint256 sendForLock) public {
        _run(guessHash, sendForLock);
    }

    receive() external payable {}
}
